import{_ as p,r as n,o as i,c as g,a as e,e as o,w as t,b as s,d as c}from"./app-116bd22d.js";const m="/MyBlog/assets/image-20240821144039738-361d9ce7.png",d="/MyBlog/assets/image-20240821144055453-9bd0da9b.png",r="/MyBlog/assets/image-20240821144113967-ef292ccc.png",l="/MyBlog/assets/image-20240821144129679-6714aa5d.png",_="/MyBlog/assets/image-20240821144153599-36d3a66c.png",h="/MyBlog/assets/image-20240821144217683-3370bb43.png",u="/MyBlog/assets/image-20240821144240977-78331ca3.png",f="/MyBlog/assets/image-20240821144323777-8988f101.png",b="/MyBlog/assets/image-20240821144534708-4406ca3e.png",B="/MyBlog/assets/image-20240821144620876-1fcbeed8.png",y="/MyBlog/assets/image-20240821144647133-c06c8cd1.png",M="/MyBlog/assets/image-20240821144843064-2fd7eba5.png",x="/MyBlog/assets/image-20240821144951831-4d6a8575.png",j="/MyBlog/assets/image-20240821145017133-d70df0f6.png",N="/MyBlog/assets/image-20240821145037545-596b25b0.png",q="/MyBlog/assets/image-20240821145109010-24043ff2.png",w="/MyBlog/assets/image-20240821145127983-4d10966a.png",E="/MyBlog/assets/image-20240821145150755-a2598026.png",v="/MyBlog/assets/image-20240821145226994-07fee4b9.png",J="/MyBlog/assets/image-20240821145245012-fb90891b.png",k="/MyBlog/assets/image-20240821145315052-6cad46f2.png",C="/MyBlog/assets/image-20240821145343581-fbe510b9.png",V={},X=e("h1",{id:"✨node-js和npm的安装与环境配置",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#✨node-js和npm的安装与环境配置","aria-hidden":"true"},"#"),s(" ✨node.js和npm的安装与环境配置")],-1),A=e("hr",null,null,-1),D={class:"table-of-contents"},R=c('<h2 id="安装node-js" tabindex="-1"><a class="header-anchor" href="#安装node-js" aria-hidden="true">#</a> 安装node.js</h2><p>1、进入官网下载：node.js官网 我选择的是windows64位的，你可以根据自己的实际情况选择对应的版本。</p><p><img src="'+m+'" alt="image-20240821144039738"></p><p>2、下载完成，安装。 打开安装程序</p><p><img src="'+d+'" alt="image-20240821144055453"></p><p>接受协议</p><p><img src="'+r+'" alt="image-20240821144113967"></p><p>选择安装位置，一会儿还要用。我选择的是：E:\\NodeJs 选择完之后直接下一步</p><p><img src="'+l+'" alt="image-20240821144129679"></p><p>下一步，next即可</p><p><img src="'+_+'" alt="image-20240821144153599"></p><p><img src="'+h+'" alt="image-20240821144217683"></p><p>点击install，等待安装完成</p><p><img src="'+u+'" alt="image-20240821144240977"></p><h3 id="测试是否安装成功" tabindex="-1"><a class="header-anchor" href="#测试是否安装成功" aria-hidden="true">#</a> 测试是否安装成功</h3><p>win+r输入cmd打开<strong>命令行</strong>，输入<code>node</code>，如下图显示，表示安装成功，我安装的版本是18.18.0.</p><p><img src="'+f+'" alt="image-20240821144323777"></p><h3 id="测试npm" tabindex="-1"><a class="header-anchor" href="#测试npm" aria-hidden="true">#</a> 测试npm</h3><p>由于node.js默认配置了npm，所以不用单独下载和配置npm了，<strong>node.js安装</strong>只要成功，那么是直接可以使用npm命令来下载moudle的。 win+r输入cmd打开命令行，输入<code>npm -v</code>，显示当前npm版本。</p><p><img src="'+b+'" alt="image-20240821144534708"></p><h3 id="环境配置" tabindex="-1"><a class="header-anchor" href="#环境配置" aria-hidden="true">#</a> 环境配置</h3><p>这里主要配置的是改变npm下载的模块包的默认存储地址，如果你的C盘容量非常大，你已经可以直接使用，不用再进行下面的配置。 为什么要改变默认存储地址呢？ 因为nodejs默认全局仓库是在c盘下面的，你可以通过<code>npm list -global</code>命令查看 (查看不了的话就使用管理员模式打开命令行再使用指令)</p><p><img src="'+B+'" alt="image-20240821144620876"></p><p>可以看到默认路径不仅非常复杂，而且位于c盘下，以后你只要使用npm install XXXX -g的命令，都会将包存储进去。所以可以将全局仓库重新改变位置，让它和nodejs的安装目录一直，也更加方便管理。 我的nodejs的安装目录是：E:\\NodeJs 首先在E:\\NodeJs下新建两个文件夹 node_global node_cache</p><p><img src="'+y+'" alt="image-20240821144647133"></p><p>命令行输入指令 <code>npm config set prefix &quot;E:\\NodeJs\\node_global&quot;</code> 这里需要把&quot;&quot;中的地址改为自己的node_global的地址 指令执行结束之后使用<code>npm list -g</code>查看是否更改成功</p><p><img src="'+M+'" alt="image-20240821144843064"></p><p>（正常情况下是出现empty的，但是由于我已经全部配置好了就显示这样）</p><p>命令行中输入：<code>npm config set cache &quot;E:\\NodeJs\\node_cache&quot;</code> 更改默认缓存位置</p><p>更改结束之后，下面我们运行<code>npm install express -g</code>来测试一下（如果安装报错，请使用管理员身份打开命令行进行安装）</p><p><img src="'+x+'" alt="image-20240821144951831"></p><p>再次输入<code>npm list -g</code></p><p><img src="'+j+'" alt="image-20240821145017133"></p><p>新目录下也出现了express</p><p><img src="'+N+'" alt="image-20240821145037545"></p><h4 id="更改环境变量" tabindex="-1"><a class="header-anchor" href="#更改环境变量" aria-hidden="true">#</a> 更改环境变量</h4><p>接下来就要更改环境变量了 计算机右键点击属性，找到高级系统设置，点开。</p><p><img src="'+q+'" alt="image-20240821145109010"></p><p><img src="'+w+'" alt="image-20240821145127983"></p><p>选中path，点击编辑</p><p><img src="'+E+'" alt="image-20240821145150755"></p><p>将原来的C:\\Users\\用户名\\AppData\\Roaming\\npm更改为新的地址，确认。</p><p><img src="'+v+'" alt="image-20240821145226994"></p><h4 id="新建系统变量" tabindex="-1"><a class="header-anchor" href="#新建系统变量" aria-hidden="true">#</a> 新建系统变量</h4><p><img src="'+J+'" alt="image-20240821145245012"></p><p><img src="'+k+'" alt="image-20240821145315052"></p><p>这里修改为自己的modules地址</p><p><img src="'+C+'" alt="image-20240821145343581"></p>',48);function S(T,U){const a=n("router-link");return i(),g("div",null,[X,A,e("nav",D,[e("ul",null,[e("li",null,[o(a,{to:"#安装node-js"},{default:t(()=>[s("安装node.js")]),_:1}),e("ul",null,[e("li",null,[o(a,{to:"#测试是否安装成功"},{default:t(()=>[s("测试是否安装成功")]),_:1})]),e("li",null,[o(a,{to:"#测试npm"},{default:t(()=>[s("测试npm")]),_:1})]),e("li",null,[o(a,{to:"#环境配置"},{default:t(()=>[s("环境配置")]),_:1})])])])])]),R])}const F=p(V,[["render",S],["__file","index.html.vue"]]);export{F as default};
